#!/usr/bin/env python3
"""dump.py [-m] [-raw] 'cmd1;;cmd2' : run the original (or mine with -m) with the commands, save, and show clouds."""
import sys, os, json, base64, zlib, struct, tempfile, shutil
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
MINE = '/workspace/.claude/worktrees/agent-a2ffdd25819f1e2dc/target/release/bimcraft-cli'
args = sys.argv[1:]
exe = None
raw = False
while args and args[0].startswith('-'):
    if args[0] == '-m': exe = MINE
    if args[0] == '-raw': raw = True
    args = args[1:]
a = ['run']
for p in args[0].split(';;'):
    a += ['--cmd', p.strip()]
a += ['--save', 'out.bimcraft']
d = tempfile.mkdtemp(prefix='dump')
out, res = run(a, cwd=d, exe=exe)
print('exit', out[0]); print(out[1].strip()); print(out[2].strip())
if 'out.bimcraft' in res:
    doc = json.loads(res['out.bimcraft'])
    keys = list(doc.keys())
    print('top keys:', keys)
    for name, c in (doc.get('clouds') or {}).items():
        print('cloud', repr(name), {k: v for k, v in c.items() if k not in ('points', 'colours')})
        for k in ('points', 'colours'):
            if k in c:
                b = base64.b64decode(c[k])
                if raw: print('  ', k, 'zlib', b.hex())
                u = zlib.decompress(b)
                if k == 'points':
                    f = struct.unpack('<%df' % (len(u) // 4), u)
                    pts = [f[i:i + 3] for i in range(0, len(f), 3)]
                    print('  points', len(pts), pts[:12], '...' if len(pts) > 12 else '')
                else:
                    print('  colours', len(u), [tuple(u[i:i + 3]) for i in range(0, min(len(u), 36), 3)])
    for k, v in doc['elements'].items():
        if v.get('category') == 'pointcloud':
            print('element', k, json.dumps(v))
    for k, v in doc['library'].items():
        if v.get('kind') == 'cloud':
            print('library', k, json.dumps(v))
shutil.rmtree(d)

