#!/usr/bin/env python3
"""gen.py kind n out [seed] : write a test cloud.
kinds: xyz-grid (integer grid in m), xyz-rand (random floats), pts-rand, ply-bin-rand, las-rand"""
import sys, random, struct
kind, n, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
seed = int(sys.argv[4]) if len(sys.argv) > 4 else 1
rnd = random.Random(seed)
if kind == 'xyz-grid':
    with open(out, 'w') as f:
        for i in range(n):
            f.write('%d %d %d\n' % (i % 100, (i // 100) % 100, i // 10000))
elif kind == 'xyz-rand':
    with open(out, 'w') as f:
        for i in range(n):
            f.write('%.4f %.4f %.4f\n' % (rnd.uniform(0, 50), rnd.uniform(0, 30), rnd.uniform(0, 10)))
elif kind == 'xyz-rand-rgb':
    with open(out, 'w') as f:
        for i in range(n):
            f.write('%.4f %.4f %.4f %d %d %d\n' % (rnd.uniform(0, 50), rnd.uniform(0, 30), rnd.uniform(0, 10), rnd.randrange(256), rnd.randrange(256), rnd.randrange(256)))
elif kind == 'pts-rand':
    with open(out, 'w') as f:
        f.write('%d\n' % n)
        for i in range(n):
            f.write('%.4f %.4f %.4f %d %d %d %d\n' % (rnd.uniform(0, 50), rnd.uniform(0, 30), rnd.uniform(0, 10), rnd.randrange(-2048, 2048), rnd.randrange(256), rnd.randrange(256), rnd.randrange(256)))
elif kind == 'ply-rand':
    with open(out, 'wb') as f:
        f.write(b'ply\nformat binary_little_endian 1.0\nelement vertex %d\nproperty float x\nproperty float y\nproperty float z\nproperty uchar red\nproperty uchar green\nproperty uchar blue\nend_header\n' % n)
        buf = bytearray()
        for i in range(n):
            buf += struct.pack('<fffBBB', rnd.uniform(0, 50), rnd.uniform(0, 30), rnd.uniform(0, 10), rnd.randrange(256), rnd.randrange(256), rnd.randrange(256))
        f.write(buf)
elif kind == 'ply-grid':
    with open(out, 'wb') as f:
        f.write(b'ply\nformat binary_little_endian 1.0\nelement vertex %d\nproperty float x\nproperty float y\nproperty float z\nend_header\n' % n)
        buf = bytearray()
        for i in range(n):
            buf += struct.pack('<fff', (i % 100) * 0.01, ((i // 100) % 100) * 0.01, (i // 10000) * 0.01)
        f.write(buf)
else:
    raise SystemExit('unknown kind')

