#!/usr/bin/env python3
"""dumpall.py [-m] [extra-json] : for each good asset, show cloud data (orig, or mine with -m)."""
import sys, os, json, base64, zlib, struct, tempfile, shutil
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
MINE = '/workspace/.claude/worktrees/agent-a2ffdd25819f1e2dc/target/release/bimcraft-cli'
args = sys.argv[1:]
exe = None
if args and args[0] == '-m':
    exe = MINE; args = args[1:]
extra = args[0] if args else ''
files = args[1:] if len(args) > 1 else None
D = '/workspace/assets/test_cloud_formats'
for f in files or sorted(os.listdir(D)):
    if f.startswith('bad_'): continue
    d = tempfile.mkdtemp(prefix='dump')
    path = f if f.startswith('/') else D + '/' + f
    out, res = run(['run', '--cmd', 'point_cloud {"path": "%s"%s}' % (path, extra), '--save', 'out.bimcraft'], cwd=d, exe=exe)
    print('==', f, out[0], out[1].strip().split('\n')[0], out[2].strip())
    if 'out.bimcraft' in res:
        doc = json.loads(res['out.bimcraft'])
        for name, c in (doc.get('clouds') or {}).items():
            print('  ', {k: v for k, v in c.items() if k not in ('points', 'colours')})
            for k in ('points', 'colours'):
                if k in c:
                    u = zlib.decompress(base64.b64decode(c[k]))
                    if k == 'points':
                        fl = struct.unpack('<%df' % (len(u) // 4), u)
                        print('   points', [fl[i:i + 3] for i in range(0, min(len(fl), 30), 3)])
                    else:
                        print('   colours', [tuple(u[i:i + 3]) for i in range(0, min(len(u), 30), 3)])
        for k, v in doc['elements'].items():
            if v.get('category') == 'pointcloud':
                print('   element at', v['at'], 'offset', v['offset'], 'angle', v['angle'])
    shutil.rmtree(d)

