#!/usr/bin/env python3
import sys, struct
def logical(b, page=1024):
    out = bytearray()
    for i in range(0, len(b), page):
        out += b[i:i + page - 4]
    return bytes(out)
def phys_to_log(off, page=1024):
    return (off // page) * (page - 4) + off % page
for f in sys.argv[1:]:
    b = open(f, 'rb').read()
    print('==', f, len(b), 'bytes')
    if len(b) < 48:
        print(' short', b.hex()); continue
    sig = b[:8]
    maj, mnr, plen, xoff, xlen, psize = struct.unpack('<IIQQQQ', b[8:48])
    print(' sig', sig, 'version', maj, mnr, 'physlen', plen, 'xml phys off', xoff, 'xml log len', xlen, 'page', psize)
    L = logical(b)
    xs = phys_to_log(xoff)
    print(' XML:')
    print(L[xs:xs + xlen].decode('utf-8', 'replace'))
    print(' binary before xml (logical 48..xml):', L[48:min(xs, 48 + 400)].hex())

