#!/usr/bin/env python3
"""zcmp.py: compare the original's zlib of colour bytes with mine (dtest) for generated data.
usage: zcmp.py mode n [seed] [count]"""
import sys, os, json, base64, zlib, subprocess, random, tempfile, shutil
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
DT = '/tmp/cloud-agent/dtest/target/release/dtest'

def gen(mode, n, rnd):
    if mode == 'rand':
        return bytes(rnd.randrange(256) for _ in range(3 * n))
    if mode == 'small':  # few distinct values
        return bytes(rnd.choice((10, 20, 30, 40)) for _ in range(3 * n))
    if mode == 'text':
        words = [b'alpha', b'beta', b'gamma', b'delta', b'epsilon', b'zeta', b'eta', b'theta']
        s = bytearray()
        while len(s) < 3 * n:
            s += rnd.choice(words) + b' '
        return bytes(s[:3 * n])
    if mode == 'const':
        return bytes([200]) * (3 * n)
    if mode == 'runs':
        s = bytearray()
        while len(s) < 3 * n:
            s += bytes([rnd.randrange(2, 256)]) * rnd.randrange(1, 40)
        return bytes(s[:3 * n])
    if mode == 'mix':
        s = bytearray()
        while len(s) < 3 * n:
            k = rnd.randrange(4)
            if k == 0: s += bytes(rnd.randrange(256) for _ in range(rnd.randrange(1, 300)))
            elif k == 1 and len(s) > 10:
                d = rnd.randrange(1, min(len(s), 40000)); l = rnd.randrange(3, 300)
                for _ in range(l): s.append(s[-d])
            elif k == 2: s += bytes([rnd.randrange(256)]) * rnd.randrange(1, 600)
            else: s += bytes(rnd.choice((7, 8, 9, 100)) for _ in range(rnd.randrange(1, 100)))
        return bytes(s[:3 * n])
    raise SystemExit('mode?')

def orig_zlib(col, d):
    n = len(col) // 3
    with open(os.path.join(d, 'c.xyz'), 'w') as f:
        for i in range(n):
            f.write('%d 0 0 %d %d %d\n' % (i, col[3 * i], col[3 * i + 1], col[3 * i + 2]))
    out, res = run(['run', '--cmd', 'point_cloud {"path": "c.xyz", "units": "mm"}', '--save', 'o.bimcraft'], cwd=d)
    if 'o.bimcraft' not in res:
        print('orig failed', out); return None
    doc = json.loads(res['o.bimcraft'])
    c = doc['clouds']['c']
    return base64.b64decode(c['colours']), base64.b64decode(c['points'])

def mine(data):
    return subprocess.run([DT], input=data, capture_output=True).stdout

if __name__ == '__main__':
    mode, n = sys.argv[1], int(sys.argv[2])
    seed = int(sys.argv[3]) if len(sys.argv) > 3 else 1
    count = int(sys.argv[4]) if len(sys.argv) > 4 else 1
    bad = 0
    for k in range(count):
        rnd = random.Random(seed + k)
        col = gen(mode, n, rnd)
        if max(col) <= 1:
            col = bytes([2]) + col[1:]
        d = tempfile.mkdtemp(prefix='z')
        r = orig_zlib(col, d)
        shutil.rmtree(d)
        if r is None: bad += 1; continue
        o, pts = r
        assert zlib.decompress(o) == col, 'colour data differs from what we wrote'
        m = mine(col)
        if o != m:
            bad += 1
            # first differing byte
            i = next((i for i in range(min(len(o), len(m))) if o[i] != m[i]), min(len(o), len(m)))
            print('DIFF mode=%s n=%d seed=%d: orig %d bytes, mine %d bytes, first diff at %d' % (mode, n, seed + k, len(o), len(m), i))
            print('  orig', o[:64].hex()); print('  mine', m[:64].hex())
        else:
            print('same mode=%s n=%d seed=%d (%d -> %d bytes)' % (mode, n, seed + k, len(col), len(o)))
    print('bad', bad, 'of', count)

