#!/usr/bin/env python3
"""Find the order the point_cloud command checks its parameters in."""
import sys, json, itertools
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
good = '/tmp/cloud-agent/f/a.pts'
bad = {
    'name': 5,
    'name_empty': '',
    'level': 'nope',
    'at': 5,
    'offset': 'x',
    'angle': 'x',
    'units': 'km',
    'units_t': 5,
    'spacing': 'x',
    'spacing_neg': -1,
    'origin': 'x',
    'origin_t': 5,
    'path_missing': '/tmp/cloud-agent/f/nope.pts',
    'path_ext': '/tmp/cloud-agent/f/nope.abc',
    'path_t': 5,
}
def key(k): return k.split('_')[0]
def err(params):
    out, _ = run(['run', '--cmd', 'point_cloud ' + json.dumps(params)])
    return (out[1] + out[2]).strip().replace('line 1 (point_cloud): point_cloud: ', '')
names = list(bad)
single = {}
for k in names:
    p = {'path': good}
    p[key(k)] = bad[k]
    single[k] = err(p)
    print('%-14s %s' % (k, single[k]))
print()
wins = {k: set() for k in names}
for a, b in itertools.combinations(names, 2):
    if key(a) == key(b): continue
    p = {'path': good}
    p[key(a)] = bad[a]; p[key(b)] = bad[b]
    e = err(p)
    if e == single[a]: wins[a].add(b)
    elif e == single[b]: wins[b].add(a)
    else: print('neither', a, b, e)
for k in sorted(names, key=lambda k: -len(wins[k])):
    print('%-14s beats %d: %s' % (k, len(wins[k]), sorted(wins[k])))

