#!/usr/bin/env python3
"""tfile.py [-m] srcfile ext [extra-json] : copy srcfile to t.<ext> in a temp dir, import with the original (and mine)."""
import sys, os, json, base64, zlib, struct, tempfile, shutil
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
MINE = '/workspace/.claude/worktrees/agent-a2ffdd25819f1e2dc/target/release/bimcraft-cli'
args = sys.argv[1:]
both = False
if args and args[0] == '-m':
    both = True; args = args[1:]
src, ext = args[0], args[1]
extra = args[2] if len(args) > 2 else ''
data = open(src, 'rb').read()
def go(exe):
    d = tempfile.mkdtemp(prefix='tf')
    open(os.path.join(d, 't.' + ext), 'wb').write(data)
    out, res = run(['run', '--cmd', 'point_cloud {"path": "t.%s"%s}' % (ext, extra), '--save', 'o.bimcraft'], cwd=d, exe=exe)
    lines = []
    lines.append('(%d) %s' % (out[0], (out[1].split('\n')[0] + out[2]).strip()))
    if 'o.bimcraft' in res and out[0] == 0:
        doc = json.loads(res['o.bimcraft'])
        for name, c in (doc.get('clouds') or {}).items():
            lines.append('   ' + str({k: v for k, v in c.items() if k not in ('points', 'colours')}))
            for k in ('points', 'colours'):
                if k in c:
                    u = zlib.decompress(base64.b64decode(c[k]))
                    if k == 'points':
                        fl = struct.unpack('<%df' % (len(u) // 4), u)
                        lines.append('   points %s' % [fl[i:i + 3] for i in range(0, min(len(fl), 30), 3)])
                    else:
                        lines.append('   colours %s' % [tuple(u[i:i + 3]) for i in range(0, min(len(u), 30), 3)])
        for k, v in doc['elements'].items():
            if v.get('category') == 'pointcloud':
                lines.append('   at %s offset %s angle %s' % (v['at'], v['offset'], v['angle']))
    shutil.rmtree(d)
    return '\n'.join(lines)
o = go(None)
print(o)
if both:
    m = go(MINE)
    if m != o:
        print('--- MINE DIFFERS:'); print(m)
    else:
        print('--- mine same')

