"""runcorpus.py [-m] [-x extra-json] [pattern...] : run every corpus file (or those matching patterns) through
the original (and compare with mine with -m). Prints the original's result per case, or SAME/DIFF with -m.
Results of the original are cached in /tmp/cloud-agent/cache/."""
import sys, os, json, base64, zlib, struct, tempfile, shutil, hashlib, fnmatch
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0, '/tmp/cloud-agent')
from orig import run
MINE = '/workspace/.claude/worktrees/agent-a2ffdd25819f1e2dc/target/release/bimcraft-cli'
D = '/tmp/cloud-agent/corpus'
C = '/tmp/cloud-agent/cache'
os.makedirs(C, exist_ok=True)
args = sys.argv[1:]
both = False; extra = ''; verbose = False
while args and args[0].startswith('-'):
    if args[0] == '-m': both = True; args = args[1:]
    elif args[0] == '-v': verbose = True; args = args[1:]
    elif args[0] == '-x': extra = args[1]; args = args[2:]
    else: break
pats = args or ['*']
files = sorted(f for f in os.listdir(D) if any(fnmatch.fnmatch(f, p) for p in pats))
import re
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)
def go(f, exe):
    d = tempfile.mkdtemp(prefix='rc')
    shutil.copy(os.path.join(D, f), os.path.join(d, f))
    out, res = run(['run', '--cmd', 'point_cloud {"path": "%s"%s}' % (f, extra), '--save', 'o.bimcraft'], cwd=d, exe=exe)
    shutil.rmtree(d)
    r = {'code': out[0], 'stdout': out[1], 'stderr': out[2]}
    if 'o.bimcraft' in res:
        r['file'] = norm(res['o.bimcraft'].decode('utf-8'))
    return r
def summary(r):
    s = '(%d) %s%s' % (r['code'], r['stdout'].split('\n')[0], r['stderr'].strip())
    if 'file' in r and r['code'] == 0:
        doc = json.loads(r['file'])
        for name, c in (doc.get('clouds') or {}).items():
            s += '\n     ' + str({k: v for k, v in c.items() if k not in ('points', 'colours')})
            u = zlib.decompress(base64.b64decode(c['points']))
            fl = struct.unpack('<%df' % (len(u) // 4), u)
            s += '\n     pts ' + str([fl[i:i + 3] for i in range(0, min(len(fl), 15), 3)])
            if 'colours' in c:
                u = zlib.decompress(base64.b64decode(c['colours']))
                s += '\n     col ' + str([tuple(u[i:i + 3]) for i in range(0, min(len(u), 15), 3)])
        for k, v in doc['elements'].items():
            if v.get('category') == 'pointcloud':
                s += '\n     at %s offset %s' % (v['at'], v['offset'])
    return s
def orig_cached(f):
    data = open(os.path.join(D, f), 'rb').read()
    h = hashlib.sha1(data + extra.encode() + f.encode()).hexdigest()
    cp = os.path.join(C, h + '.json')
    if os.path.exists(cp):
        return json.load(open(cp))
    r = go(f, None)
    json.dump(r, open(cp, 'w'))
    return r
def job(f):
    o = orig_cached(f)
    if not both:
        return f, summary(o), None
    m = go(f, MINE)
    same = o == m
    return f, summary(o), (None if same else summary(m))
nd = 0
with ThreadPoolExecutor(8) as ex:
    for f, so, sm in ex.map(job, files):
        if not both:
            print('%-34s %s' % (f, so))
        elif sm is None:
            if verbose: print('SAME %-34s %s' % (f, so.split('\n')[0]))
        else:
            nd += 1
            print('DIFF %-34s\n  O: %s\n  M: %s' % (f, so, sm))
if both:
    print('%d of %d differ' % (nd, len(files)))

