#!/usr/bin/env python3
"""A small E57 reader for analysis: prints scans, prototypes and decoded records."""
import sys, struct, math
import xml.etree.ElementTree as ET
PAGE = 1024
def logical_bytes(b):
    out = bytearray()
    for i in range(0, len(b), PAGE):
        out += b[i:i + PAGE - 4]
    return bytes(out)
def p2l(off):
    return (off // PAGE) * (PAGE - 4) + off % PAGE
def strip(tag):
    return tag.split('}')[-1]
def bits_for(lo, hi):
    n = hi - lo
    return 0 if n <= 0 else n.bit_length()
def fields_of(proto):
    out = []
    for f in proto:
        name = strip(f.tag); t = f.get('type')
        if t == 'Float':
            prec = f.get('precision', 'double')
            out.append((name, t, 32 if prec == 'single' else 64, f.attrib))
        elif t in ('Integer', 'ScaledInteger'):
            lo = int(f.get('minimum', '-9223372036854775808')); hi = int(f.get('maximum', '9223372036854775807'))
            out.append((name, t, bits_for(lo, hi), f.attrib))
        else:
            out.append((name, t, None, f.attrib))
    return out
def decode(L, off, count, fields):
    s = p2l(off)
    sid = L[s]; slen, dpo, ipo = struct.unpack('<QQQ', L[s + 8:s + 32])
    print('   section id %d loglen %d dataphys %d indexphys %d' % (sid, slen, dpo, ipo))
    pos = p2l(dpo)
    end = s + slen
    streams = [bytearray() for _ in fields]
    while pos < end:
        ptype, pflags, plm1 = struct.unpack('<BBH', L[pos:pos + 4])
        plen = plm1 + 1
        if ptype == 1:
            nst = struct.unpack('<H', L[pos + 4:pos + 6])[0]
            lens = struct.unpack('<%dH' % nst, L[pos + 6:pos + 6 + 2 * nst])
            q = pos + 6 + 2 * nst
            for i, l in enumerate(lens):
                if i < len(streams): streams[i] += L[q:q + l]
                q += l
            print('   data packet len %d streams %s' % (plen, lens))
        else:
            print('   packet type %d len %d' % (ptype, plen))
        pos += plen
    recs = []
    vals = []
    for (name, t, bits, a), st in zip(fields, streams):
        v = []
        if t == 'Float':
            fmt = '<f' if bits == 32 else '<d'
            n = bits // 8
            for i in range(count):
                v.append(struct.unpack(fmt, bytes(st[i * n:(i + 1) * n]))[0] if (i + 1) * n <= len(st) else None)
        else:
            lo = int(a.get('minimum', '0'))
            bi = int.from_bytes(bytes(st), 'little')
            for i in range(count):
                raw = (bi >> (i * bits)) & ((1 << bits) - 1) if bits else 0
                x = raw + lo
                if t == 'ScaledInteger':
                    x = x * float(a.get('scale', '1')) + float(a.get('offset', '0'))
                v.append(x)
        vals.append(v)
    for i in range(count):
        recs.append({f[0]: vals[k][i] for k, f in enumerate(fields)})
    return recs
for fn in sys.argv[1:]:
    b = open(fn, 'rb').read()
    print('==', fn)
    maj, mnr, plen, xoff, xlen, psize = struct.unpack('<IIQQQQ', b[8:48])
    L = logical_bytes(b)
    xs = p2l(xoff)
    xml = L[xs:xs + xlen]
    try:
        root = ET.fromstring(xml)
    except Exception as e:
        print(' xml error', e); continue
    for d3 in root:
        if strip(d3.tag) != 'data3D': continue
        for k, vc in enumerate(d3):
            print(' scan', k)
            pts = None; pose = None
            for c in vc:
                tg = strip(c.tag)
                if tg == 'points': pts = c
                elif tg == 'pose':
                    pose = {strip(x.tag): {strip(y.tag): y.text for y in x} for x in c}
                    print('  pose', pose)
                elif tg in ('colorLimits', 'intensityLimits', 'cartesianBounds', 'sphericalBounds'):
                    print('  ', tg, {strip(y.tag): y.text for y in c})
            if pts is None: print('  no points'); continue
            proto = [c for c in pts if strip(c.tag) == 'prototype'][0]
            fields = fields_of(proto)
            print('  fields', [(f[0], f[1], f[2]) for f in fields])
            off = int(pts.get('fileOffset')); cnt = int(pts.get('recordCount'))
            print('  offset', off, 'count', cnt)
            try:
                recs = decode(L, off, cnt, fields)
                for r in recs[:12]: print('   ', r)
            except Exception as e:
                print('  decode error', e)

