//! PLY, as text or binary in either byte order: the header (up to `end_header` in its first MiB),
//! the elements before the vertices stepped over, and the vertices' x, y and z, their colour
//! (red, green and blue; r, g and b; or diffuse_red…) and their intensity.

use super::read::{Raw, Source};

#[derive(Clone, Copy, PartialEq, Debug)]
enum Ty {
    I8,
    U8,
    I16,
    U16,
    I32,
    U32,
    F32,
    F64,
}

impl Ty {
    fn parse(s: &str) -> Option<Ty> {
        Some(match s {
            "char" | "int8" => Ty::I8,
            "uchar" | "uint8" => Ty::U8,
            "short" | "int16" => Ty::I16,
            "ushort" | "uint16" => Ty::U16,
            "int" | "int32" => Ty::I32,
            "uint" | "uint32" => Ty::U32,
            "float" | "float32" => Ty::F32,
            "double" | "float64" => Ty::F64,
            _ => return None,
        })
    }
    fn size(self) -> usize {
        match self {
            Ty::I8 | Ty::U8 => 1,
            Ty::I16 | Ty::U16 => 2,
            Ty::I32 | Ty::U32 | Ty::F32 => 4,
            Ty::F64 => 8,
        }
    }
    fn is_float(self) -> bool {
        matches!(self, Ty::F32 | Ty::F64)
    }
    fn get(self, b: &[u8], big: bool) -> f64 {
        macro_rules! rd {
            ($t:ty, $n:expr) => {{
                let mut a = [0u8; $n];
                a.copy_from_slice(&b[..$n]);
                if big {
                    <$t>::from_be_bytes(a) as f64
                } else {
                    <$t>::from_le_bytes(a) as f64
                }
            }};
        }
        match self {
            Ty::I8 => b[0] as i8 as f64,
            Ty::U8 => b[0] as f64,
            Ty::I16 => rd!(i16, 2),
            Ty::U16 => rd!(u16, 2),
            Ty::I32 => rd!(i32, 4),
            Ty::U32 => rd!(u32, 4),
            Ty::F32 => rd!(f32, 4),
            Ty::F64 => rd!(f64, 8),
        }
    }
}

struct Prop {
    name: String,
    /// None for a list.
    ty: Option<Ty>,
}

struct Element {
    name: String,
    count: u64,
    props: Vec<Prop>,
}

#[derive(Clone, Copy, PartialEq)]
enum Enc {
    Ascii,
    Le,
    Be,
}

pub struct Ply<'a> {
    body: &'a [u8],
    enc: Enc,
    /// Elements before the vertices: their names, counts and record sizes (binary).
    before: Vec<(String, u64, usize)>,
    count: u64,
    /// The vertex record: each property's type, and its offset (binary) or column (text).
    props: Vec<Ty>,
    offsets: Vec<usize>,
    size: usize,
    xyz: [usize; 3],
    rgb: Option<[usize; 3]>,
    intensity: Option<usize>,
    float_rgb: bool,
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if hay.len() < needle.len() {
        return None;
    }
    (0..=hay.len() - needle.len()).find(|&i| &hay[i..i + needle.len()] == needle)
}

fn prop_index(props: &[Prop], names: &[&str]) -> Option<usize> {
    for n in names {
        if let Some(i) = props.iter().position(|p| p.name.eq_ignore_ascii_case(n)) {
            return Some(i);
        }
    }
    None
}

impl<'a> Ply<'a> {
    pub fn new(data: &'a [u8]) -> Result<Ply<'a>, String> {
        if !data.starts_with(b"ply") {
            return Err("it isn't a PLY file: it doesn't start with ply".into());
        }
        let head = &data[..data.len().min(1 << 20)];
        let end = find(head, b"end_header").ok_or_else(|| "its header has no end_header".to_string())?;
        let header = std::str::from_utf8(&data[..end]).map_err(|_| "its header isn't text".to_string())?;
        let after = end + b"end_header".len();
        let body_start = match data[after..].iter().position(|b| *b == b'\n') {
            Some(i) => after + i + 1,
            None => data.len(),
        };
        let body = &data[body_start..];

        let mut enc = None;
        let mut elements: Vec<Element> = Vec::new();
        for line in header.split('\n').skip(1) {
            let t = line.trim();
            let toks: Vec<&str> = t.split_whitespace().collect();
            if toks.is_empty() {
                continue;
            }
            let bad = || format!("its header says \"{}\", which isn't PLY", t);
            match toks[0] {
                "comment" | "obj_info" => {}
                "format" => {
                    if toks.len() != 3 {
                        return Err(bad());
                    }
                    enc = Some(match toks[1] {
                        "ascii" => Enc::Ascii,
                        "binary_little_endian" => Enc::Le,
                        "binary_big_endian" => Enc::Be,
                        other => {
                            return Err(format!(
                                "its format is {}: PLY is ascii, binary_little_endian or binary_big_endian",
                                other
                            ))
                        }
                    });
                }
                "element" => {
                    if toks.len() != 3 {
                        return Err(bad());
                    }
                    let count: u64 =
                        toks[2].parse().map_err(|_| format!("element {} {}: not a count", toks[1], toks[2]))?;
                    elements.push(Element { name: toks[1].to_string(), count, props: Vec::new() });
                }
                "property" => {
                    let el = elements.last_mut().ok_or_else(|| "a property before any element".to_string())?;
                    if toks.get(1) == Some(&"list") {
                        if toks.len() != 5 {
                            return Err(bad());
                        }
                        el.props.push(Prop { name: toks[4].to_string(), ty: None });
                    } else {
                        if toks.len() != 3 {
                            return Err(bad());
                        }
                        let ty = Ty::parse(toks[1]).ok_or_else(|| {
                            format!("property {} is of type {}, which PLY doesn't have", toks[2], toks[1])
                        })?;
                        el.props.push(Prop { name: toks[2].to_string(), ty: Some(ty) });
                    }
                }
                _ => return Err(bad()),
            }
        }
        let enc = enc.ok_or_else(|| "its header has no format".to_string())?;
        let vi = elements
            .iter()
            .position(|e| e.name == "vertex")
            .ok_or_else(|| "it has no vertex element".to_string())?;
        let v = &elements[vi];
        if v.props.iter().any(|p| p.ty.is_none()) {
            return Err("its vertices hold a list, which a point can't".into());
        }
        let mut xyz = [0usize; 3];
        for (k, n) in ["x", "y", "z"].iter().enumerate() {
            xyz[k] = prop_index(&v.props, &[n]).ok_or_else(|| format!("its vertices have no {}", n))?;
        }
        let r = prop_index(&v.props, &["red", "r", "diffuse_red"]);
        let g = prop_index(&v.props, &["green", "g", "diffuse_green"]);
        let b = prop_index(&v.props, &["blue", "b", "diffuse_blue"]);
        let rgb = match (r, g, b) {
            (Some(r), Some(g), Some(b)) => Some([r, g, b]),
            _ => None,
        };
        let intensity = prop_index(&v.props, &["intensity", "scalar_intensity"]);
        let props: Vec<Ty> = v.props.iter().map(|p| p.ty.unwrap()).collect();
        let mut offsets = Vec::with_capacity(props.len());
        let mut size = 0;
        for t in &props {
            offsets.push(size);
            size += t.size();
        }
        let float_rgb = rgb.map(|c| c.iter().any(|i| props[*i].is_float())).unwrap_or(false);
        let mut before = Vec::new();
        for e in &elements[..vi] {
            if enc != Enc::Ascii && e.props.iter().any(|p| p.ty.is_none()) {
                return Err(format!(
                    "its {} elements, before its vertices, hold a list, which BIMCraft can't step over",
                    e.name
                ));
            }
            let sz: usize = e.props.iter().map(|p| p.ty.map(|t| t.size()).unwrap_or(0)).sum();
            before.push((e.name.clone(), e.count, sz));
        }
        Ok(Ply { body, enc, before, count: v.count, props, offsets, size, xyz, rgb, intensity, float_rgb })
    }

    fn raw_of(&self, val: &dyn Fn(usize) -> f64) -> Raw {
        let p = [val(self.xyz[0]), val(self.xyz[1]), val(self.xyz[2])];
        let rgb = self.rgb.map(|c| {
            let mut v = [val(c[0]), val(c[1]), val(c[2])];
            if self.float_rgb {
                for x in v.iter_mut() {
                    *x *= 255.0;
                }
            }
            v
        });
        let intensity = self.intensity.map(val);
        Raw { p, rgb, intensity, rgb8: None }
    }
}

impl<'a> Source for Ply<'a> {
    fn each(&mut self, f: &mut dyn FnMut(&Raw) -> Result<(), String>) -> Result<(), String> {
        match self.enc {
            Enc::Ascii => {
                let mut lines = self.body.split(|b| *b == b'\n');
                for (name, count, _) in &self.before {
                    let mut left = *count;
                    while left > 0 {
                        match lines.next() {
                            None => return Err(format!("it's cut short in its {} elements", name)),
                            Some(l) => {
                                if l.iter().all(|b| b.is_ascii_whitespace()) {
                                    continue;
                                }
                                left -= 1;
                            }
                        }
                    }
                }
                let mut n: u64 = 0;
                let mut vals: Vec<f64> = vec![0.0; self.props.len()];
                while n < self.count {
                    let l = match lines.next() {
                        None => return Err(format!("it's cut short: {} vertices of {}", n, self.count)),
                        Some(l) => l,
                    };
                    let s = std::str::from_utf8(l).map_err(|_| format!("vertex {} isn't text", n + 1))?;
                    let mut toks = s.split_whitespace().peekable();
                    if toks.peek().is_none() {
                        continue;
                    }
                    for (k, slot) in vals.iter_mut().enumerate() {
                        let _ = k;
                        let tok = toks.next().ok_or_else(|| format!("vertex {} has too few values", n + 1))?;
                        *slot = tok.parse().map_err(|_| format!("vertex {}: {} isn't a number", n + 1, tok))?;
                    }
                    for tok in toks {
                        let _: f64 = tok.parse().map_err(|_| format!("vertex {}: {} isn't a number", n + 1, tok))?;
                    }
                    n += 1;
                    let raw = self.raw_of(&|i| vals[i]);
                    f(&raw)?;
                }
                Ok(())
            }
            Enc::Le | Enc::Be => {
                let big = self.enc == Enc::Be;
                let mut off: u128 = 0;
                for (_, count, sz) in &self.before {
                    off += *count as u128 * *sz as u128;
                }
                let need = self.count as u128 * self.size as u128;
                if off + need > self.body.len() as u128 {
                    return Err(format!("it's cut short: {} vertices don't fit in it", self.count));
                }
                let mut pos = off as usize;
                for _ in 0..self.count {
                    let rec = &self.body[pos..pos + self.size];
                    pos += self.size;
                    let props = &self.props;
                    let offsets = &self.offsets;
                    let raw = self.raw_of(&|i| props[i].get(&rec[offsets[i]..], big));
                    f(&raw)?;
                }
                Ok(())
            }
        }
    }
}

//! ASPRS LAS 1.0 to 1.4, uncompressed: the public header, then point records of formats 0 to 10,
//! each scaled and offset, with their intensity, and their colour where the format has one.

use super::read::{Raw, Source};

/// Each point format's record length, and where its colour is (if it has one).
const FORMATS: [(usize, Option<usize>); 11] = [
    (20, None),
    (28, None),
    (26, Some(20)),
    (34, Some(28)),
    (57, None),
    (63, Some(28)),
    (30, None),
    (36, Some(30)),
    (38, Some(30)),
    (59, None),
    (67, Some(30)),
];

pub struct Las<'a> {
    data: &'a [u8],
    offset: usize,
    count: u64,
    reclen: usize,
    rgb_at: Option<usize>,
    scale: [f64; 3],
    add: [f64; 3],
}

fn u16_at(b: &[u8], i: usize) -> u16 {
    u16::from_le_bytes([b[i], b[i + 1]])
}
fn u32_at(b: &[u8], i: usize) -> u32 {
    u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
}
fn u64_at(b: &[u8], i: usize) -> u64 {
    let mut a = [0u8; 8];
    a.copy_from_slice(&b[i..i + 8]);
    u64::from_le_bytes(a)
}
fn f64_at(b: &[u8], i: usize) -> f64 {
    f64::from_bits(u64_at(b, i))
}

impl<'a> Las<'a> {
    pub fn new(data: &'a [u8]) -> Result<Las<'a>, String> {
        if !data.starts_with(b"LASF") {
            return Err("it isn't a LAS file: it doesn't start with LASF".into());
        }
        if data.len() < 227 {
            return Err("its header is cut short".into());
        }
        let (major, minor) = (data[24], data[25]);
        if major != 1 || minor > 4 {
            return Err(format!("it's LAS {}.{}; BIMCraft reads 1.0 to 1.4", major, minor));
        }
        let hsize = u16_at(data, 94) as usize;
        if hsize < 227 || data.len() < hsize {
            return Err("its header is cut short".into());
        }
        let offset = u32_at(data, 96) as u64;
        let fmt = data[104];
        let reclen = u16_at(data, 105) as usize;
        let legacy = u32_at(data, 107) as u64;
        if fmt & 0xC0 != 0 {
            return Err("its points are compressed (LAZ): decompress it to LAS first (laszip or PDAL)".into());
        }
        if fmt > 10 {
            return Err(format!("its point format {} isn't one LAS has (0 to 10)", fmt));
        }
        let (need, rgb_at) = FORMATS[fmt as usize];
        if reclen < need {
            return Err(format!("its point records are {} bytes; point format {} needs {}", reclen, fmt, need));
        }
        let mut scale = [0.0; 3];
        let mut add = [0.0; 3];
        let axes = ["x", "y", "z"];
        for k in 0..3 {
            scale[k] = f64_at(data, 131 + 8 * k);
            add[k] = f64_at(data, 155 + 8 * k);
            if scale[k] == 0.0 || !scale[k].is_finite() {
                return Err(format!("its scale along {} is {}", axes[k], scale[k]));
            }
            if !add[k].is_finite() {
                return Err(format!("its offset along {} is {}", axes[k], add[k]));
            }
        }
        let count = if legacy != 0 {
            legacy
        } else if minor >= 4 && hsize >= 375 {
            u64_at(data, 247)
        } else {
            0
        };
        let end = offset as u128 + count as u128 * reclen as u128;
        if offset < hsize as u64 || end > data.len() as u128 {
            return Err(format!(
                "its points are cut short: {} of {} bytes from byte {} don't fit in {} bytes",
                count,
                reclen,
                offset,
                data.len()
            ));
        }
        Ok(Las { data, offset: offset as usize, count, reclen, rgb_at, scale, add })
    }
}

impl<'a> Source for Las<'a> {
    fn each(&mut self, f: &mut dyn FnMut(&Raw) -> Result<(), String>) -> Result<(), String> {
        let mut pos = self.offset;
        for _ in 0..self.count {
            let r = &self.data[pos..pos + self.reclen];
            pos += self.reclen;
            let mut p = [0.0; 3];
            for k in 0..3 {
                let raw = i32::from_le_bytes([r[4 * k], r[4 * k + 1], r[4 * k + 2], r[4 * k + 3]]);
                p[k] = raw as f64 * self.scale[k] + self.add[k];
            }
            let intensity = Some(u16_at(r, 12) as f64);
            let rgb = self.rgb_at.map(|a| [u16_at(r, a) as f64, u16_at(r, a + 2) as f64, u16_at(r, a + 4) as f64]);
            f(&Raw { p, rgb, intensity, rgb8: None })?;
        }
        Ok(())
    }
}

//! Point clouds: PTS, XYZ, PLY, LAS and E57 scans, and the `point_cloud` command.
//!
//! A project holds each scan once, by name, in its file's `clouds` (a library entry of kind
//! `cloud` gives it an id and a GUID): the file it came from (and its stations'), where its
//! middle was there, how many points the file held, and the points kept, as little-endian
//! `f32` about that middle, and their colours, each deflated and in base64. A `pointcloud`
//! element places a scan: its `cloud` (the library entry's GUID), its `level`, its middle at
//! `at` and `offset` over the level, turned `angle` degrees.

pub mod e57;
pub mod las;
pub mod ply;
pub mod read;
pub mod text;
pub mod xml;

use crate::commands::params::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use read::{Format, Options, Scan, MAX_CLOUDS, MAX_CLOUD_POINTS, MAX_STATIONS};

const CMD: &str = "point_cloud";

/// Runs the commands this module owns; None for the others.
pub fn dispatch(s: &mut Session, cid: &str, p: &Value) -> Option<Result<Value, String>> {
    match cid {
        "point_cloud" => Some(cmd_point_cloud(s, p)),
        _ => None,
    }
}

fn err<T>(msg: String) -> Result<T, String> {
    Err(format!("{}: {}", CMD, msg))
}

/// A file's name, as a scan keeps where it came from.
fn file_name(path: &str) -> String {
    std::path::Path::new(path).file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
}

fn file_stem(path: &str) -> String {
    std::path::Path::new(path).file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
}

/// The `path` parameter: one file or a list of a scan's stations.
fn paths_param(p: &Value) -> Result<Option<Vec<String>>, String> {
    match p.get("path") {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Str(s)) => Ok(Some(vec![s.clone()])),
        Some(Value::Arr(a)) => {
            if a.is_empty() {
                return err("`path` is a scan file, or a list of the files of one scan's stations, not an empty list".into());
            }
            if a.len() > MAX_STATIONS {
                return err(format!("a scan comes from up to {} files, not {}", MAX_STATIONS, a.len()));
            }
            let mut out = Vec::new();
            for v in a {
                match v {
                    Value::Str(s) => out.push(s.clone()),
                    _ => return err(format!("`path` lists files by their paths, not {}", v.to_compact())),
                }
            }
            Ok(Some(out))
        }
        Some(v) => err(format!(
            "`path` is a scan file, or a list of the files of one scan's stations, not {}",
            v.to_compact()
        )),
    }
}

/// mm in each of a file's units.
fn units_scale(u: &str) -> Option<f64> {
    Some(match u.trim().to_lowercase().as_str() {
        "mm" => 1.0,
        "cm" => 10.0,
        "m" => 1000.0,
        "in" => 25.4,
        "ft" => 304.8,
        _ => return None,
    })
}

#[derive(PartialEq)]
enum Origin {
    Centre,
    File,
}

/// The `point_cloud` command.
pub fn cmd_point_cloud(s: &mut Session, p: &Value) -> Result<Value, String> {
    let level = crate::model::level_param(&s.project, CMD, p, "level")?;
    let paths = paths_param(p)?;
    let cloud = opt_text(p, CMD, "cloud")?;
    match (&paths, &cloud) {
        (Some(_), Some(_)) => {
            return err("give `path`, a scan file to bring in, or `cloud`, a scan the project holds; not both".into())
        }
        (None, None) => {
            return err("give `path`, a scan file (PTS, XYZ, PLY, LAS or E57) to bring in, or `cloud`, the name of a scan the project holds".into())
        }
        _ => {}
    }
    if let Some(name) = cloud {
        return place_held(s, p, level, &name);
    }
    let paths = paths.unwrap();
    let mut formats = Vec::new();
    for path in &paths {
        match Format::from_path(path) {
            Ok(f) => formats.push(f),
            Err(e) => return err(format!("{}: {}", path, e)),
        }
    }
    let name = match opt_text(p, CMD, "name")? {
        Some(n) => n,
        None => file_stem(&paths[0]),
    };
    if name.trim().is_empty() {
        return err("a scan needs a `name`".into());
    }
    if clouds(&s.project).map(|m| m.contains(&name)).unwrap_or(false) {
        return err(format!(
            "the project already holds a scan named `{}`: place it again with `cloud`, or bring this file in under another `name`",
            name
        ));
    }
    let held = clouds(&s.project).map(|m| m.len()).unwrap_or(0);
    if held >= MAX_CLOUDS {
        return err(format!("the project holds {} scans already; delete the point clouds of one first", held));
    }
    let scale = match opt_text(p, CMD, "units")? {
        None => 1000.0,
        Some(u) => match units_scale(&u) {
            Some(x) => x,
            None => return err(format!("`units` is one of mm, cm, m, in, ft, not {}", u)),
        },
    };
    let spacing = opt_num(p, CMD, "spacing")?.unwrap_or(0.0);
    let total = total_points(&s.project);
    if total >= MAX_CLOUD_POINTS {
        return err(format!(
            "the project's scans hold {} points, all it may; delete the point clouds of one first",
            total
        ));
    }
    let left = MAX_CLOUD_POINTS - total;
    let mut stations: Vec<(String, Scan)> = Vec::new();
    let share = left / paths.len() as u64;
    for (path, fmt) in paths.iter().zip(formats.iter()) {
        let opts = Options { scale, cap: if paths.len() == 1 { left } else { share }, spacing };
        match read::read(path, *fmt, &opts) {
            Ok(sc) => stations.push((file_name(path), sc)),
            Err(e) => return err(format!("{}: {}", path, e)),
        }
    }
    let (scan, station_list) = if stations.len() == 1 {
        (stations.pop().unwrap().1, None)
    } else {
        let list: Vec<(String, usize)> = Vec::new();
        let (sc, counts) = merge(&stations, spacing);
        let mut list = list;
        for ((n, _), c) in stations.iter().zip(counts) {
            list.push((n.clone(), c));
        }
        (sc, Some(list))
    };
    let origin_mode = origin_param(p)?;
    let min_z = scan.points.iter().map(|q| q[2]).fold(f32::INFINITY, f32::min);
    let (at, offset, angle) = placement(&s.project, p, level, &origin_mode, &scan.origin, min_z)?;

    let entry = cloud_entry(&file_name(&paths[0]), station_list.as_deref(), &scan);
    let pr = &mut s.project;
    let (_lid, lguid) = pr.lib_add("cloud", &name);
    {
        let sec = pr.section_mut("clouds");
        sec.insert_sorted(&name, entry);
    }
    remember(&name_key(pr, &name), &scan);
    let id = place_element(pr, &lguid, level, at, offset, angle);
    Ok(reply(&name, id, &scan.origin, scan.points.len() as u64, scan.read))
}

fn reply(name: &str, id: u64, origin: &[f64; 3], points: u64, read: u64) -> Value {
    jobj! {
        "cloud" => name,
        "id" => id,
        "origin" => Value::Arr(origin.iter().map(|x| Value::f(*x)).collect()),
        "points" => points,
        "read" => read,
    }
}

fn origin_param(p: &Value) -> Result<Origin, String> {
    match opt_text(p, CMD, "origin")? {
        None => Ok(Origin::Centre),
        Some(o) => match o.as_str() {
            "centre" | "center" => Ok(Origin::Centre),
            "file" => Ok(Origin::File),
            _ => err(format!(
                "`origin` is centre (its middle on `at`, its foot on the level) or file (where its file puts it), not {}",
                o
            )),
        },
    }
}

/// Where the element goes: `at`, `offset` and `angle`, from the parameters or the scan.
fn placement(
    pr: &Project,
    p: &Value,
    level: u64,
    mode: &Origin,
    origin: &[f64; 3],
    min_z: f32,
) -> Result<([f64; 2], f64, f64), String> {
    if *mode == Origin::File && origin.iter().any(|v| !(v.abs() <= MAX_MM)) {
        return err(format!(
            "the scan's middle lies at {:?} mm in its file, past the {} mm a model reaches: place it by its `centre`",
            origin, MAX_MM as u64
        ));
    }
    let at = opt_point(p, CMD, "at")?;
    let offset = opt_num(p, CMD, "offset")?;
    let angle = opt_num(p, CMD, "angle")?;
    let elev = crate::model::elev(pr, level);
    let at = at.unwrap_or(match mode {
        Origin::File => [origin[0], origin[1]],
        Origin::Centre => [0.0, 0.0],
    });
    let offset = offset.unwrap_or(match mode {
        Origin::File => origin[2] - elev,
        Origin::Centre => -(min_z as f64),
    });
    Ok((at, offset, angle.unwrap_or(0.0)))
}

fn place_element(pr: &mut Project, cloud_guid: &str, level: u64, at: [f64; 2], offset: f64, angle: f64) -> u64 {
    let id = pr.alloc_id();
    let lg = pr.guid_of(level).unwrap_or_default();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "pointcloud",
            "cloud" => cloud_guid,
            "level" => lg,
            "at" => Value::Arr(vec![Value::f(at[0]), Value::f(at[1])]),
            "offset" => Value::f(offset),
            "angle" => Value::f(angle),
        },
    );
    id
}

/// Places a scan the project holds again.
fn place_held(s: &mut Session, p: &Value, level: u64, name: &str) -> Result<Value, String> {
    let entry = match clouds(&s.project).and_then(|m| m.get(name)) {
        Some(e) => e.clone(),
        None => {
            let names: Vec<String> = clouds(&s.project).map(|m| m.keys().cloned().collect()).unwrap_or_default();
            return err(format!(
                "the project holds no scan named `{}` (it holds: {})",
                name,
                if names.is_empty() { "none".to_string() } else { names.join(", ") }
            ));
        }
    };
    let info = info_of(&entry);
    let origin = entry_origin(&entry);
    let mode = origin_param(p)?;
    let (at, offset, angle) = placement(&s.project, p, level, &mode, &origin, info.min_z)?;
    let pr = &mut s.project;
    let lguid = match pr.lib_guid("cloud", name) {
        Some(g) => g,
        None => pr.lib_add("cloud", name).1,
    };
    let id = place_element(pr, &lguid, level, at, offset, angle);
    let read = entry.get("read").and_then(|v| v.as_u64()).unwrap_or(0);
    Ok(reply(name, id, &origin, info.count, read))
}

fn entry_origin(e: &Value) -> [f64; 3] {
    let mut o = [0.0; 3];
    if let Some(a) = e.get("origin").and_then(|v| v.as_arr()) {
        for k in 0..3 {
            o[k] = a.get(k).and_then(|v| v.as_f64()).unwrap_or(0.0);
        }
    }
    o
}

/// The project file's entry for a scan.
fn cloud_entry(source: &str, stations: Option<&[(String, usize)]>, scan: &Scan) -> Value {
    let mut m = Map::new();
    m.insert("source", Value::s(source));
    if let Some(st) = stations {
        m.insert(
            "stations",
            Value::Arr(st.iter().map(|(n, c)| jobj! {"source" => n.as_str(), "points" => *c as u64}).collect()),
        );
    }
    m.insert("origin", Value::Arr(scan.origin.iter().map(|x| Value::f(*x)).collect()));
    m.insert("read", Value::u(scan.read));
    let mut pts = Vec::with_capacity(scan.points.len() * 12);
    for q in &scan.points {
        for v in q {
            pts.extend_from_slice(&v.to_le_bytes());
        }
    }
    m.insert("points", Value::Str(crate::util::base64_encode(&crate::deflate::zlib_compress(&pts))));
    if let Some(c) = &scan.colours {
        let mut b = Vec::with_capacity(c.len() * 3);
        for x in c {
            b.extend_from_slice(x);
        }
        m.insert("colours", Value::Str(crate::util::base64_encode(&crate::deflate::zlib_compress(&b))));
    }
    Value::Obj(m)
}

/// Stations brought together about the middle of them all, one point kept in each cube of
/// `spacing` across them, a station with no colours grey among ones with.
fn merge(stations: &[(String, Scan)], spacing: f64) -> (Scan, Vec<usize>) {
    let mut lo = [f64::INFINITY; 3];
    let mut hi = [f64::NEG_INFINITY; 3];
    for (_, sc) in stations {
        for q in &sc.points {
            for k in 0..3 {
                let v = sc.origin[k] + q[k] as f64;
                if v < lo[k] {
                    lo[k] = v;
                }
                if v > hi[k] {
                    hi[k] = v;
                }
            }
        }
    }
    let any_points = lo[0].is_finite();
    let origin = if any_points {
        [(lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0, (lo[2] + hi[2]) / 2.0]
    } else {
        [0.0; 3]
    };
    let with_colour = stations.iter().any(|(_, s)| s.colours.is_some());
    let mut seen: std::collections::HashSet<[i64; 3]> = std::collections::HashSet::new();
    let mut points = Vec::new();
    let mut colours = Vec::new();
    let mut counts = Vec::new();
    let mut read = 0;
    for (_, sc) in stations {
        read += sc.read;
        let mut n = 0;
        for (i, q) in sc.points.iter().enumerate() {
            let a = [sc.origin[0] + q[0] as f64, sc.origin[1] + q[1] as f64, sc.origin[2] + q[2] as f64];
            if spacing > 0.0 {
                let key = read::cube(&a, &lo, spacing);
                if !seen.insert(key) {
                    continue;
                }
            }
            points.push([(a[0] - origin[0]) as f32, (a[1] - origin[1]) as f32, (a[2] - origin[2]) as f32]);
            if with_colour {
                colours.push(match &sc.colours {
                    Some(c) => c[i],
                    None => [read::GREY; 3],
                });
            }
            n += 1;
        }
        counts.push(n);
    }
    (Scan { origin, points, colours: if with_colour { Some(colours) } else { None }, read }, counts)
}

// ---------------------------------------------------------------- the project's scans

/// The project's scans, by name.
pub fn clouds(pr: &Project) -> Option<&Map> {
    pr.section("clouds")
}

/// What a scan's points come to: how many, and the lowest.
#[derive(Clone, Copy)]
pub struct Info {
    pub count: u64,
    pub min_z: f32,
}

fn cache() -> &'static std::sync::Mutex<std::collections::HashMap<u64, Info>> {
    static C: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<u64, Info>>> = std::sync::OnceLock::new();
    C.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// A cheap key for a scan's packed points: its length and its ends (where zlib's checksum is).
fn key_of(points: &str) -> u64 {
    let b = points.as_bytes();
    let n = b.len();
    let mut k = Vec::with_capacity(80);
    k.extend_from_slice(&(n as u64).to_le_bytes());
    k.extend_from_slice(&b[..n.min(32)]);
    k.extend_from_slice(&b[n.saturating_sub(32)..]);
    crate::util::fnv1a64(&k)
}

fn name_key(pr: &Project, name: &str) -> String {
    clouds(pr)
        .and_then(|m| m.get(name))
        .and_then(|e| e.get("points"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_default()
}

fn remember(points_b64: &str, scan: &Scan) {
    let min_z = scan.points.iter().map(|q| q[2]).fold(f32::INFINITY, f32::min);
    cache().lock().unwrap().insert(key_of(points_b64), Info { count: scan.points.len() as u64, min_z });
}

/// A scan's points, unpacked.
pub fn unpack_points(e: &Value, cap: usize) -> Option<Vec<[f32; 3]>> {
    let s = e.get("points")?.as_str()?;
    let z = crate::util::base64_decode(s)?;
    let raw = crate::inflate::zlib_decode(&z, cap).ok()?;
    Some(raw.chunks_exact(12).map(|c| {
        [
            f32::from_le_bytes([c[0], c[1], c[2], c[3]]),
            f32::from_le_bytes([c[4], c[5], c[6], c[7]]),
            f32::from_le_bytes([c[8], c[9], c[10], c[11]]),
        ]
    }).collect())
}

/// How many points a scan holds, and its lowest.
pub fn info_of(e: &Value) -> Info {
    let s = e.get("points").and_then(|v| v.as_str()).unwrap_or("");
    let k = key_of(s);
    if let Some(i) = cache().lock().unwrap().get(&k) {
        return *i;
    }
    let pts = unpack_points(e, (MAX_CLOUD_POINTS as usize + 1) * 12).unwrap_or_default();
    let min_z = pts.iter().map(|q| q[2]).fold(f32::INFINITY, f32::min);
    let i = Info { count: pts.len() as u64, min_z };
    cache().lock().unwrap().insert(k, i);
    i
}

/// The points the project's scans hold among them.
pub fn total_points(pr: &Project) -> u64 {
    clouds(pr).map(|m| m.iter().map(|(_, e)| info_of(e).count).sum()).unwrap_or(0)
}

/// After a command: a scan that nothing places any more goes, with its library entry.
pub fn drop_unplaced(pr: &mut Project) {
    let names: Vec<String> = match clouds(pr) {
        Some(m) => m.keys().cloned().collect(),
        None => return,
    };
    let placed: std::collections::HashSet<String> = pr
        .elements
        .values()
        .filter(|e| e.get("category").and_then(|c| c.as_str()) == Some("pointcloud"))
        .filter_map(|e| e.get("cloud").and_then(|c| c.as_str()).map(|s| s.to_string()))
        .collect();
    let mut gone = Vec::new();
    for n in names {
        let g = pr.lib_guid("cloud", &n);
        let used = g.as_ref().map(|g| placed.contains(g)).unwrap_or(false);
        if !used {
            gone.push((n, pr.lib_find("cloud", &n)));
        }
    }
    if gone.is_empty() {
        return;
    }
    for (n, lid) in gone {
        if let Some(Value::Obj(m)) = pr.doc.get_mut("clouds") {
            m.remove(&n);
        }
        if let Some(id) = lid {
            pr.library.remove(&id);
        }
    }
    if clouds(pr).map(|m| m.is_empty()).unwrap_or(false) {
        pr.remove_top("clouds");
    }
}

/// The model rules this module owns, checked after every command.
pub fn check(pr: &crate::project::Project) -> Result<(), String> {
    let _ = pr;
    Ok(())
}

