#!/usr/bin/env python3
"""A flexible E57 writer for probing: scans with prototypes, values, packet splitting, poses, extra XML."""
import struct, math, zlib

PAGE = 1024
LOG = PAGE - 4

def crc32c(data):
    crc = 0xFFFFFFFF
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ 0x82F63B78 if crc & 1 else crc >> 1
    return crc ^ 0xFFFFFFFF

def l2p(off):
    return (off // LOG) * PAGE + off % LOG

def bits_for(lo, hi):
    n = hi - lo
    return 0 if n <= 0 else n.bit_length()

class Field:
    def __init__(self, name, typ='Float', precision='single', minimum=None, maximum=None, scale=None, offset=None, text='0', extra=''):
        self.name, self.typ, self.precision = name, typ, precision
        self.minimum, self.maximum, self.scale, self.offset, self.text, self.extra = minimum, maximum, scale, offset, text, extra
    def xml(self):
        a = ' type="%s"' % self.typ
        if self.typ == 'Float':
            if self.precision is not None:
                a += ' precision="%s"' % self.precision
            if self.minimum is not None: a += ' minimum="%s"' % self.minimum
            if self.maximum is not None: a += ' maximum="%s"' % self.maximum
            return '<%s%s%s/>' % (self.name, a, self.extra)
        if self.minimum is not None: a += ' minimum="%s"' % self.minimum
        if self.maximum is not None: a += ' maximum="%s"' % self.maximum
        if self.scale is not None: a += ' scale="%s"' % self.scale
        if self.offset is not None: a += ' offset="%s"' % self.offset
        return '<%s%s%s>%s</%s>' % (self.name, a, self.extra, self.text, self.name)
    def nbits(self):
        if self.typ == 'Float':
            return 32 if self.precision == 'single' else 64
        lo = int(self.minimum) if self.minimum is not None else -(1 << 63)
        hi = int(self.maximum) if self.maximum is not None else (1 << 63) - 1
        return bits_for(lo, hi)
    def pack(self, values):
        """bytes of the bitstream for these values"""
        if self.typ == 'Float':
            fmt = '<f' if self.precision == 'single' else '<d'
            return b''.join(struct.pack(fmt, v) for v in values)
        nb = self.nbits()
        lo = int(self.minimum) if self.minimum is not None else -(1 << 63)
        acc = 0
        for i, v in enumerate(values):
            if self.typ == 'ScaledInteger':
                raw = int(v)  # raw integer given directly
            else:
                raw = int(v)
            acc |= ((raw - lo) & ((1 << nb) - 1)) << (i * nb) if nb else 0
        total = nb * len(values)
        return acc.to_bytes((total + 7) // 8, 'little') if total else b''

class Scan:
    def __init__(self, fields, records, pose=None, name='scan', extra_xml='', chunk=None, codecs='', points_tag='points',
