"""Compare json.rs fmt_f64 with a serde_json-like formatting (Python repr digits) on many values."""
import struct, random, subprocess, math
def ryu_like(x):
    # serde_json: integers-valued floats as "N.0" when exponent small; uses ryu shortest digits.
    if x == 0:
        return '-0.0' if math.copysign(1, x) < 0 else '0.0'
    r = repr(x)
    # convert Python repr to serde_json style
    neg = r.startswith('-')
    if neg: r = r[1:]
    if 'e' in r or 'E' in r:
        m, e = r.split('e'); e = int(e)
        digits = m.replace('.', '')
        k = e + 1
    else:
        if '.' in r:
            a, b = r.split('.')
        else:
            a, b = r, ''
        a = a.lstrip('0')
        if a:
            digits = (a + b).rstrip('0') or '0'
            k = len(a)
        else:
            nz = len(b) - len(b.lstrip('0'))
            digits = b.lstrip('0').rstrip('0')
            k = -nz
    digits = digits.rstrip('0') or '0'
    length = len(digits)
    kk = k
    out = '-' if neg else ''
    kz = kk - length
    if 0 <= kz and kk <= 16:
        out += digits + '0' * (kk - length) + '.0'
    elif 0 < kk <= 16:
        out += digits[:kk] + '.' + digits[kk:]
    elif -5 < kk <= 0:
        out += '0.' + '0' * (-kk) + digits
    else:
        out += digits[0]
        if length > 1: out += '.' + digits[1:]
        out += 'e' + ('+' if kk - 1 > 0 else '') + str(kk - 1) if False else ''
        out += 'e' + str(kk - 1)
    return out
rnd = random.Random(3)
vals = []
for _ in range(200000):
    k = rnd.randrange(4)
    if k == 0:
        f = struct.unpack('<f', struct.pack('<I', rnd.getrandbits(32)))[0]
        if math.isnan(f) or math.isinf(f): continue
        vals.append(f)
    elif k == 1:
        f = struct.unpack('<f', struct.pack('<f', rnd.uniform(-1e5, 1e5)))[0]
