"""Does a PNG's IDAT stream match my zlib compressor on the same raw data?"""
import sys, struct, zlib, subprocess, base64, json
DT = '/tmp/cloud-agent/dtest/target/release/dtest'
def idat(png):
    assert png[:8] == b'\x89PNG\r\n\x1a\n'
    pos = 8; data = b''
    while pos < len(png):
        n = struct.unpack('>I', png[pos:pos + 4])[0]; t = png[pos + 4:pos + 8]
        if t == b'IDAT': data += png[pos + 8:pos + 8 + n]
        pos += 12 + n
    return data
for f in sys.argv[1:]:
    if f.endswith('.bimcraft'):
        d = json.load(open(f))
        pngs = [base64.b64decode(v['png']) for v in d.get('images', {}).values()]
    else:
        pngs = [open(f, 'rb').read()]
    for png in pngs:
        z = idat(png)
        raw = zlib.decompress(z)
        mine = subprocess.run([DT], input=raw, capture_output=True).stdout
        print(f, 'idat', len(z), 'raw', len(raw), 'header', z[:2].hex(), 'MATCH' if mine == z else 'differ (mine %d bytes)' % len(mine))

