#!/usr/bin/env python3
"""Do a PDF's Flate streams match my compressor at their zlib header's level?"""
import sys, re, zlib, subprocess
DT = '/tmp/cloud-agent/dtest/target/release/dtest'
LEVEL_OF = {0x01: 1, 0x5e: 2, 0x9c: 6, 0xda: 9}
tot = ok = 0
for f in sys.argv[1:]:
    b = open(f, 'rb').read()
    for m in re.finditer(rb'/Length (\d+)[^>]*/FlateDecode[^>]*>>\s*stream\r?\n', b):
        n = int(m.group(1)); s = m.end()
        z = b[s:s + n]
        try:
            raw = zlib.decompress(z)
        except Exception as e:
            print(f, 'stream not zlib', e); continue
        lvl = LEVEL_OF.get(z[1], 6)
        res = []
        for L in ([lvl] if len(sys.argv) < 2 else [lvl]):
            mine = subprocess.run([DT, str(L)], input=raw, capture_output=True).stdout
            res.append(mine == z)
        tot += 1; ok += res[0]
        if not res[0]:
            print(f, 'stream', s, 'len', n, 'raw', len(raw), 'header', z[:2].hex(), 'DIFFER at level', lvl, 'mine', len(mine))
print('%d of %d streams match' % (ok, tot))

