def rand_value(depth=0):
    k = rnd.randrange(12)
    if k == 0: return None
    if k == 1: return rnd.choice([True, False])
    if k == 2: return rnd.randrange(-5, 10)
    if k == 3: return rnd.choice([0.5, -1.5, 1e13, 3.0, 1e300, 2.5e7])
    if k == 4: return rnd.choice(['', 'x', 'a', 'st', '!!', 'eAFjYA==', '100000', '00000000-0000-4000-8000-000000000000'])
    if k == 5 and depth < 2: return [rand_value(depth + 1) for _ in range(rnd.randrange(0, 4))]
